git checkout -b fix/issue-7-refresh-loop && cat > src/auth.js <<'EOF'
// Refreshes the session when its cookie expired.
// fetchSession() supplies a new session; it is passed in because it is not defined in this repo yet.
export function refresh(session, fetchSession) {
  if (session.expired) return fetchSession();
  return session;
}
EOF
